SELECT (percentile_cont(0.75) within GROUP (ORDER BY los) - percentile_cont(0.25) within GROUP (ORDER BY los)) AS interquartile_range FROM icustays WHERE subject_id IN (SELECT subject_id FROM patients WHERE gender = 'M' AND age(CURRENT_DATE, date_trunc('year', birth_date)) = 86 AND EXTRACT(YEAR FROM date_trunc('year', admission_date)) BETWEEN 2019 AND 2020 AND diagnosis_code = '40101001');